import random


def package_total(records):
    total = 0
    for _, packages in records:
        if type(packages) is not int or packages < 1:
            raise ValueError("Expected a positive integer package count")
        total += packages
    return total


def capped_total(records):
    return sum(min(packages, 5) for _, packages in records)


generator = random.Random(7)
for trial in range(200):
    rows = [(str(i), generator.randint(1, 8)) for i in range(generator.randint(0, 4))]
    if capped_total(rows) != package_total(rows):
        print("counterexample at trial", trial, rows)
        print("oracle:", package_total(rows), "candidate:", capped_total(rows))
        break
print("fixed example agrees:", capped_total([("A", 2), ("B", 3), ("C", 1)]) == 6)

