store, receipts = {}, {}


def post(delivery_id, packages, key=None):
    if key is not None and key in receipts:
        if receipts[key] != (delivery_id, packages):
            return 409
        return 200
    store.setdefault(delivery_id, []).append(packages)
    if key is not None:
        receipts[key] = (delivery_id, packages)
    return 201


# Each "attempt" applies the write; the client only learns the last status.
print("no key:", [post("D", 4) for _ in range(3)], store["D"])
print("keyed:", [post("E", 4, key="req-E") for _ in range(3)], store["E"])
print("key reused with new body:", post("E", 9, key="req-E"), store["E"])

events = [("A", 1, "upsert", 2), ("A", 3, "delete", None), ("A", 2, "upsert", 99)]

last_write = {}
for delivery_id, _version, operation, packages in events:
    if operation == "delete":
        last_write.pop(delivery_id, None)
    else:
        last_write[delivery_id] = packages

versioned = {}
for delivery_id, version, operation, packages in events:
    prior = versioned.get(delivery_id)
    if prior is not None and version <= prior[0]:
        print("skip stale", delivery_id, "v", version, "behind v", prior[0])
        continue
    versioned[delivery_id] = (version, operation == "delete", packages)

print("arrival order:", last_write)
print("versioned visible:", {k: v[2] for k, v in versioned.items() if not v[1]})
