facts = [
    {"route": 10, "event_hour": 9, "known_hour": 9, "late_count": 1},
    {"route": 10, "event_hour": 12, "known_hour": 14, "late_count": 6},
]


def as_of(cutoff, use_known_hour):
    usable = [
        f
        for f in facts
        if f["event_hour"] <= cutoff and (not use_known_hour or f["known_hour"] <= cutoff)
    ]
    return max(usable, key=lambda f: f["event_hour"])["late_count"] if usable else None


for cutoff in (12, 13, 14):
    print(
        cutoff,
        "event clock only:",
        as_of(cutoff, False),
        "with knowledge clock:",
        as_of(cutoff, True),
    )

events = [(1, 2), (4, 3), (12, 1), (6, 5), (15, 2)]


def run(lateness):
    windows, watermark, dropped = {}, 0, []
    for arrival, (event_time, packages) in enumerate(events):
        watermark = max(watermark, event_time - lateness)
        start = event_time // 10 * 10
        if start + 10 <= watermark:
            dropped.append((event_time, arrival))
            continue
        windows[start] = windows.get(start, 0) + packages
    return windows, watermark, dropped


for lateness in (2, 6):
    print("lateness", lateness, "->", run(lateness))

snapshots = {1: ["a.parquet", "b.parquet"]}
current = 1


def commit(base, add, remove):
    global current
    if base != current:
        return "conflict: based on " + str(base) + ", current is " + str(current)
    files = [f for f in snapshots[base] if f not in remove] + add
    current = base + 1
    snapshots[current] = files
    return "committed snapshot " + str(current)


reader_snapshot = current
print(commit(1, ["c.parquet"], ["a.parquet"]))
print("reader still sees:", snapshots[reader_snapshot])
print("new reader sees:", snapshots[current])
print(commit(1, ["d.parquet"], []))

from graphlib import TopologicalSorter

inputs = {
    "raw_orders": ["clean_orders"],
    "raw_routes": ["clean_routes"],
    "clean_orders": ["daily_totals", "late_report"],
    "clean_routes": ["late_report"],
    "daily_totals": ["dashboard"],
    "late_report": [],
    "dashboard": [],
}


def downstream(changed):
    found, stack = set(), [changed]
    while stack:
        for child in inputs[stack.pop()]:
            if child not in found:
                found.add(child)
                stack.append(child)
    return found


order = list(
    TopologicalSorter(
        {k: {p for p, cs in inputs.items() if k in cs} for k in inputs}
    ).static_order()
)
for changed in ("raw_routes", "raw_orders"):
    stale = downstream(changed)
    print(changed, "->", [node for node in order if node in stale])

def calls(layers, attempts):
    return attempts**layers


for layers in (1, 2, 3):
