from collections import defaultdict

events = [
    ("D1", "2024-07-01", 1, 3),
    ("D2", "2024-07-01", 1, 2),
    ("D1", "2024-07-01", 2, 5),
    ("D3", "2024-07-02", 1, 4),
]
running = defaultdict(int)
for _delivery, day, _version, packages in events:
    running[day] += packages
latest = {}
for delivery, day, version, packages in events:
    if delivery not in latest or version > latest[delivery][1]:
        latest[delivery] = (day, version, packages)
oracle = defaultdict(int)
for day, _version, packages in latest.values():
    oracle[day] += packages
print("summing every event:", dict(running))
print("full-history oracle:", dict(oracle))
print("mismatched days:", [d for d in oracle if oracle[d] != running[d]])

designs = {
    "nightly batch": {"freshness_min": 1440, "monthly_cost": 200, "ops_people": 0.2},
    "micro-batch": {"freshness_min": 15, "monthly_cost": 900, "ops_people": 0.5},
    "streaming": {"freshness_min": 1, "monthly_cost": 3000, "ops_people": 1.5},
}
for constraints in (
    {"freshness_min": 60, "monthly_cost": 1000, "ops_people": 1.0},
    {"freshness_min": 1440, "monthly_cost": 500, "ops_people": 0.5},
):
    feasible = [
        name for name, d in designs.items() if all(d[k] <= v for k, v in constraints.items())
    ]
    cheapest = min(feasible, key=lambda name: designs[name]["monthly_cost"]) if feasible else None
    print(constraints, "feasible:", feasible, "choose:", cheapest)

